ALTER TABLE t ALTER COLUMN c SET EXPRESSION AS (a * 2);

ALTER TABLE t ALTER c SET EXPRESSION AS (a + b);

ALTER TABLE IF EXISTS ONLY t
    ALTER COLUMN c SET EXPRESSION AS (upper(name) || '_' || id::text);

ALTER TABLE t
    ALTER COLUMN c SET EXPRESSION AS (a * 3),
    ALTER COLUMN d DROP EXPRESSION;

ALTER TABLE t ALTER COLUMN d DROP EXPRESSION IF EXISTS;
